fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    // If prefix is empty, it always matches
    if p.is_empty() {
        return true;
    }
    
    // If the sequence is shorter than the prefix, it can't match
    if v.len() < p.len() {
        return false;
    }
    
    // Check each character up to the prefix length
    for i in 0..p.len() {
        if v[i] != p[i] {
            return false;
        }
    }
    
    true
}

fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    let mut filtered = Vec::new();
    
    for seq in xs {
        if has_prefix(&seq, &p) {
            filtered.push(seq);
        }
    }
    
    filtered
}